def _state_bytes(s):
    out = bytearray()
    _enc(s.cap, ('n',), out)
    _enc(s.nt, ('n',), out)
    _enc(s.label.d, ('n',), out)
    _enc(len(s.label.m), ('n',), out)
    for k, v in sorted(s.label.m.items()):
        _enc(k, ('n',), out)
        _enc(v, ('n',), out)
    _enc(s.st.d, ('n',), out)
    _enc(len(s.st.m), ('n',), out)
    for k, v in sorted(s.st.m.items()):
        _enc(k, ('n',), out)
        _enc(v, ('n',), out)
    _enc(s.rank.d, ('l', ('n',)), out)
    _enc(len(s.rank.m), ('n',), out)
    for k, v in sorted(s.rank.m.items()):
        _enc(k, ('n',), out)
        _enc(v, ('l', ('n',)), out)
    _enc(s.waiters.d, ('l', ('n',)), out)
    _enc(len(s.waiters.m), ('n',), out)
    for k, v in sorted(s.waiters.m.items()):
        _enc(k, ('n',), out)
        _enc(v, ('l', ('n',)), out)
    _enc(s.missing.d, ('n',), out)
    _enc(len(s.missing.m), ('n',), out)
    for k, v in sorted(s.missing.m.items()):
        _enc(k, ('n',), out)
        _enc(v, ('n',), out)
    _enc(s.made.d, ('n',), out)
    _enc(len(s.made.m), ('n',), out)
    for k, v in sorted(s.made.m.items()):
        _enc(k, ('r', (('n',), ('l', ('r', (('n',), ('n',)))))), out)
        _enc(v, ('n',), out)
    _enc(s.depth, ('n',), out)
    return bytes(out)


def _stepper_init(s, audit):
    s._audit = audit
    s._d_Task = []
    s.rank.w = s._d_Task
    s.st.w = s._d_Task
    s.waiters.w = s._d_Task
    s._ix_telling = _Index(3, 1)
    s._aud_telling = []
    s._ix_droppable = _Index(2, 1)
    s._aud_droppable = []
    s._ix_queue = _Index(1, 1)
    s._aud_queue = []
    for v in range(_ixbound_telling(s)):
        _ixrefresh_telling(s, v)
    for v in range(_ixbound_droppable(s)):
        _ixrefresh_droppable(s, v)
    for v in range(_ixbound_queue(s)):
        _ixrefresh_queue(s, v)
    if audit:
        _audit(s)


def _loop(s, out):
    """The output loop (docs/spec.md §3.8.3): the first enabled output in
    policy order, until none is."""
    n = 0
    while True:
        for f in _OUTS:
            if f(s, out):
                break
        else:
            return
        _refresh(s)
        n += 1
        if n >= 1 << 24:
            raise StepLimit("2^24 actions in one step")


class State:
    """The stepper of the refined Core (docs/spec.md §3.8.1, §3.8.2, §3.12.2).
    With audit, every index is checked against its definition after every
    summand (§3.9.9): tests only."""

    __slots__ = ("_s",)

    def __init__(self, config, out, audit=False):
        s = _initial(config)
        _stepper_init(s, audit)
        self._s = s
        _loop(s, out)

    def step(self, event, out):
        s = self._s
        for match, fire in _STEP.get(event[0], ()):
            env = match(s, event[1:])
            if env is not None:
                fire(s, env)
                _refresh(s)
                _loop(s, out)
                return
        raise Refused(event)

    def bytes(self):
        """An estimate of the memory the state holds (§3.13.4)."""
        n = 0
        for name in _S.__slots__:
            v = getattr(self._s, name, None)
            if isinstance(v, _Col):
                n += 16 * len(v.m)
            elif isinstance(v, (tuple, frozenset, list)):
                n += 8 * len(v)
            else:
                n += 8
        return n

    def state_bytes(self):
        """Every parameter's value, encoded as entries are (for comparing the backends)."""
        return _state_bytes(self._s)

    def read(self, name):
        """A parameter's value (a stored function as a view)."""
        return getattr(self._s, name)
